-- Synthetic interface observations explicitly authorised for the BALANCE test dataset only.
BEGIN;
DO $$ BEGIN IF current_database() <> 'monitoring_test' THEN RAISE EXCEPTION 'Base de test requise'; END IF; IF (SELECT COUNT(*) FROM atm_test_cassette_fixtures WHERE dataset_code='BALANCE_XLSX_20261012') <> 9 THEN RAISE EXCEPTION '9 GABs BALANCE requis'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM (SELECT s.status_key,COUNT(*) n FROM atm_display_status s JOIN atm_test_cassette_fixtures f ON f.atm_id=s.atm_id WHERE f.dataset_code='BALANCE_XLSX_20261012' GROUP BY s.status_key) x WHERE (x.status_key='ok' AND x.n<>3) OR (x.status_key='warning' AND x.n<>4) OR (x.status_key='error' AND x.n<>2) OR x.status_key='unknown') THEN RAISE EXCEPTION 'Répartition de test incorrecte'; END IF; END $$;
COMMIT;